update public.direct_transfer_submissions set status='awaiting_verification' where status is null;
alter table public.direct_transfer_submissions drop constraint if exists direct_transfer_proof_required;
alter table public.direct_transfer_submissions add constraint direct_transfer_proof_required check (length(trim(coalesce(proof_storage_path,'')))>0) not valid;
alter table public.direct_transfer_submissions validate constraint direct_transfer_proof_required;
create or replace function public.submit_direct_bank_transfer(p_platform text,p_invoice uuid,p_source_reference text,p_amount numeric,p_sender_name text,p_sender_bank text,p_customer_reference text,p_transferred_at timestamptz default null,p_proof_storage_path text default null) returns uuid language plpgsql security definer set search_path='public' as $$declare v_bank uuid;v_id uuid;v_enabled boolean;begin if auth.uid() is null then raise exception 'Authentication required';end if;if p_platform='datasub' then raise exception 'DataSub requires immediate automated payment and fulfilment';end if;if p_platform not in('schoolpro','host','consult','engineering','print','fabrication','compute','academy','digital_business','business_centre') then raise exception 'Direct transfer is not available for this platform';end if;if p_amount<=0 then raise exception 'Amount must be greater than zero';end if;if length(trim(coalesce(p_proof_storage_path,'')))=0 then raise exception 'Payment receipt/proof is required';end if;select direct_bank_transfer_enabled into v_enabled from payment_platform_settings where platform_code=p_platform;if not coalesce(v_enabled,false) then raise exception 'Direct bank transfer is not enabled for this platform';end if;select id into v_bank from ihlink_bank_accounts where is_active=true order by is_default desc,created_at asc limit 1;if v_bank is null then raise exception 'IHLink direct bank account has not been configured';end if;insert into direct_transfer_submissions(user_id,platform_code,invoice_id,source_reference,bank_account_id,amount,sender_name,sender_bank,customer_reference,transferred_at,proof_storage_path,status) values(auth.uid(),p_platform,p_invoice,p_source_reference,v_bank,p_amount,trim(p_sender_name),nullif(trim(p_sender_bank),''),trim(p_customer_reference),p_transferred_at,p_proof_storage_path,'awaiting_verification') returning id into v_id;return v_id;end$$;
create or replace function public.review_direct_bank_transfer(p_submission uuid,p_decision text,p_note text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare s public.direct_transfer_submissions%rowtype;new_status text;begin if not private.is_admin(array['super_admin'::public.user_role,'finance'::public.user_role]) then raise exception 'Finance or Super Admin required';end if;if p_decision not in('approved','rejected') then raise exception 'Decision must be approved or rejected';end if;select * into s from public.direct_transfer_submissions where id=p_submission for update;if s.id is null then raise exception 'Submission not found';end if;if s.status not in('awaiting_verification','pending') then raise exception 'Submission has already been reviewed';end if;if p_decision='approved' then
 if s.platform_code='consult' then update public.consult_invoices set amount_paid=least(amount,coalesce(amount_paid,0)+s.amount),status=case when coalesce(amount_paid,0)+s.amount>=amount then 'paid' else 'partial' end,paid_at=case when coalesce(amount_paid,0)+s.amount>=amount then now() else paid_at end,payment_reference=s.customer_reference,updated_at=now() where id=s.invoice_id;
 elsif s.platform_code='engineering' then update public.engineering_invoices set amount_paid=least(amount,coalesce(amount_paid,0)+s.amount),status=case when coalesce(amount_paid,0)+s.amount>=amount then 'paid' else 'partial' end,updated_at=now() where id=s.invoice_id;
 elsif s.platform_code='print' then update public.print_invoices set amount_paid=least(amount,coalesce(amount_paid,0)+s.amount),status=case when coalesce(amount_paid,0)+s.amount>=amount then 'paid' else 'partial' end,updated_at=now() where id=s.invoice_id;
 elsif s.platform_code='host' then update public.host_invoices set status=case when s.amount>=amount then 'paid' else status end,paid_at=case when s.amount>=amount then now() else paid_at end,payment_reference=s.customer_reference,updated_at=now() where id=s.invoice_id;
 elsif s.platform_code in('fabrication','compute','academy','digital_business','business_centre') then update public.business_invoices set amount_paid=least(amount,coalesce(amount_paid,0)+s.amount),status=case when coalesce(amount_paid,0)+s.amount>=amount then 'paid' else 'partial' end,updated_at=now() where id=s.invoice_id;
 end if;new_status='approved';else new_status='rejected';end if;
 update public.direct_transfer_submissions set status=new_status,admin_note=p_note,verified_by=auth.uid(),verified_at=now(),updated_at=now() where id=s.id;
 return jsonb_build_object('id',s.id,'status',new_status,'platform',s.platform_code,'invoice_id',s.invoice_id);end$$;
revoke all on function public.review_direct_bank_transfer(uuid,text,text) from public,anon;grant execute on function public.review_direct_bank_transfer(uuid,text,text) to authenticated;
revoke all on function public.submit_direct_bank_transfer(text,uuid,text,numeric,text,text,text,timestamptz,text) from public,anon;grant execute on function public.submit_direct_bank_transfer(text,uuid,text,numeric,text,text,text,timestamptz,text) to authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('direct-transfer-proofs','direct-transfer-proofs',false,5242880,array['image/jpeg','image/png','image/webp','application/pdf']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists "direct transfer proof owner upload" on storage.objects;create policy "direct transfer proof owner upload" on storage.objects for insert to authenticated with check(bucket_id='direct-transfer-proofs' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists "direct transfer proof owner read" on storage.objects;create policy "direct transfer proof owner read" on storage.objects for select to authenticated using(bucket_id='direct-transfer-proofs' and ((storage.foldername(name))[1]=auth.uid()::text or private.is_admin(array['super_admin'::public.user_role,'finance'::public.user_role])));
drop policy if exists "direct transfer proof admin delete" on storage.objects;create policy "direct transfer proof admin delete" on storage.objects for delete to authenticated using(bucket_id='direct-transfer-proofs' and private.is_admin(array['super_admin'::public.user_role,'finance'::public.user_role]));

create or replace function public.finalize_schoolpro_subscription(p_intent uuid,p_transaction_ref text,p_amount numeric) returns jsonb language plpgsql security definer set search_path='' as $$declare i public.schoolpro_subscription_intents%rowtype;c public.schoolpro_subscription_catalog%rowtype;tx public.payment_transactions%rowtype;r timestamptz;begin
if p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2) or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Verified exact subscription payment required';end if;
select * into i from public.schoolpro_subscription_intents where id=p_intent for update;if i.id is null then raise exception 'Subscription payment intent unavailable';end if;
if i.status='paid' then if i.transaction_ref=p_transaction_ref and i.amount=p_amount then return jsonb_build_object('status','already_paid','school_id',i.school_id);end if;raise exception 'Subscription intent already settled by another transaction';end if;
select * into tx from public.payment_transactions where provider='billstack' and transaction_ref=p_transaction_ref for update;
if i.status<>'pending' or i.amount<>p_amount or tx.id is null or tx.status not in('verified','credited') or tx.credited_at is not null or tx.amount<>p_amount or tx.currency<>'NGN' or tx.user_id is distinct from i.payer_user_id or tx.platform_code is distinct from 'schoolpro' or tx.virtual_account_id is distinct from i.virtual_account_id then raise exception 'Verified transaction ownership, platform or replay validation failed';end if;
select * into c from public.schoolpro_subscription_catalog where id=i.catalog_id and active=true;if c.id is null then raise exception 'Subscription plan is unavailable';end if;
r:=case i.billing_cycle when 'monthly' then now()+interval '1 month' when 'termly' then now()+interval '4 months' when 'annual' then now()+interval '1 year' else null end;if r is null then raise exception 'Unsupported billing cycle';end if;
insert into public.schoolpro_subscriptions(school_id,tier,billing_cycle,amount,status,starts_at,renews_at,managed_by_ihlink,updated_at) values(i.school_id,c.code,i.billing_cycle,i.amount,'active',now(),r,true,now()) on conflict(school_id) do update set tier=excluded.tier,billing_cycle=excluded.billing_cycle,amount=excluded.amount,status='active',starts_at=coalesce(public.schoolpro_subscriptions.starts_at,now()),renews_at=r,managed_by_ihlink=true,updated_at=now();
update public.schoolpro_subscription_intents set status='paid',transaction_ref=p_transaction_ref,paid_at=now(),updated_at=now() where id=i.id;
update public.payment_transactions set status='credited',credited_at=now(),updated_at=now() where id=tx.id;
return jsonb_build_object('status','active','school_id',i.school_id,'tier',c.code,'renews_at',r);end$$;
revoke all on function public.finalize_schoolpro_subscription(uuid,text,numeric) from public,anon,authenticated;grant execute on function public.finalize_schoolpro_subscription(uuid,text,numeric) to service_role;

