create or replace function public.schoolpro_result_class_rank(p_student_id uuid,p_term text,p_session text)
returns table(class_population bigint,class_position bigint,total_score numeric,average_score numeric)
language plpgsql security definer set search_path='' as $$
declare v_school uuid;v_class uuid;
begin
 select s.school_id,s.class_id into v_school,v_class from public.schoolpro_students s where s.id=p_student_id;
 if v_school is null or v_class is null then raise exception 'Student or class not found';end if;
 if not (private.has_school_access(v_school) or private.is_admin(array['super_admin'::public.user_role])) then raise exception 'School access required';end if;
 return query with totals as(
  select s.id,coalesce(sum(r.total_score),0)::numeric total,case when count(r.id)>0 then avg(r.total_score)::numeric else 0::numeric end avg_score
  from public.schoolpro_students s left join public.schoolpro_results r on r.student_id=s.id and r.term=p_term and r.session=p_session
  where s.school_id=v_school and s.class_id=v_class and s.status='active' group by s.id
 ),ranked as(select id,total,avg_score,rank() over(order by total desc) pos,count(*) over() pop from totals)
 select pop,pos,total,avg_score from ranked where id=p_student_id;
end $$;
