create or replace function public.schoolpro_can_view_result_output(p_student_id uuid,p_term text,p_session text)
returns boolean language sql stable security definer set search_path='' as $$
select exists(
 select 1 from public.schoolpro_results r
 where r.student_id=p_student_id and r.term=p_term and r.session=p_session and r.status='published'::public.schoolpro_result_status
 and (
  exists(select 1 from public.schoolpro_students s where s.id=p_student_id and s.user_id=(select auth.uid()))
  or exists(select 1 from public.schoolpro_guardian_links g where g.student_id=p_student_id and g.guardian_user_id=(select auth.uid()) and g.status='active')
 )
 and (
  not coalesce((select fs.block_results_when_owing from public.schoolpro_finance_settings fs where fs.school_id=r.school_id limit 1),false)
  or (
   coalesce((select sum(greatest(inv.amount_due-inv.amount_paid,0)) from public.schoolpro_invoices inv where inv.student_id=p_student_id and inv.term=p_term and inv.session=p_session and inv.status<>'waived'::public.schoolpro_invoice_status),0)
   <=coalesce((select fs.allowed_outstanding from public.schoolpro_finance_settings fs where fs.school_id=r.school_id limit 1),0)
   and not exists(select 1 from public.schoolpro_invoices inv where inv.student_id=p_student_id and inv.term=p_term and inv.session=p_session and inv.result_hold=true)
  )
 )
);
$$;
