create or replace function public.submit_direct_bank_transfer(
 p_platform text,p_invoice uuid,p_source_reference text,p_amount numeric,p_sender_name text,p_sender_bank text,
 p_customer_reference text,p_transferred_at timestamptz default null,p_proof_storage_path text default null
) returns uuid
language plpgsql security definer set search_path to ''
as $function$
declare
 v_bank uuid; v_id uuid; v_enabled boolean; v_owner uuid; v_total numeric; v_paid numeric:=0; v_unit text; v_balance numeric;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_platform='datasub' then raise exception 'DataSub requires immediate automated payment and fulfilment'; end if;
 if p_platform not in('schoolpro','host','consult','engineering','print','fabrication','compute','academy','digital_business','business_centre')
   then raise exception 'Direct transfer is not available for this platform'; end if;
 if length(trim(coalesce(p_proof_storage_path,'')))=0 then raise exception 'Payment receipt/proof is required'; end if;

 select direct_bank_transfer_enabled into v_enabled
 from public.payment_platform_settings where platform_code=p_platform;
 if not coalesce(v_enabled,false) then raise exception 'Direct bank transfer is not enabled for this platform'; end if;

 if p_platform='consult' then
   select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
   from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='engineering' then
   select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
   from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='print' then
   select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
   from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=p_invoice;
 elsif p_platform='host' then
   select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid
   from public.host_invoices i where i.id=p_invoice;
 elsif p_platform in('fabrication','compute','academy','digital_business','business_centre') then
   select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit
   from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=p_invoice;
   if v_owner is not null and v_unit<>p_platform then raise exception 'Invoice does not belong to the selected platform'; end if;
 elsif p_platform='schoolpro' then
   select coalesce(st.user_id,g.guardian_user_id),i.amount_due,coalesce(i.amount_paid,0)
   into v_owner,v_total,v_paid
   from public.schoolpro_invoices i
   join public.schoolpro_students st on st.id=i.student_id
   left join lateral (
     select gl.guardian_user_id from public.schoolpro_guardian_links gl
     where gl.student_id=st.id and gl.guardian_user_id=auth.uid() and gl.status='active' limit 1
   ) g on true
   where i.id=p_invoice and (st.user_id=auth.uid() or g.guardian_user_id=auth.uid());
 end if;

 if v_owner is null or v_owner<>auth.uid() then raise exception 'Invoice not found or does not belong to this account'; end if;
 v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
 if v_balance<=0 then raise exception 'Invoice has no outstanding balance'; end if;
 if p_amount<>v_balance then raise exception 'Transfer amount must equal the outstanding invoice balance'; end if;
 if nullif(trim(coalesce(p_sender_name,'')),'') is null or nullif(trim(coalesce(p_customer_reference,'')),'') is null
   then raise exception 'Sender name and transfer reference are required'; end if;
 if exists(select 1 from public.direct_transfer_submissions d
   where d.user_id=auth.uid() and d.platform_code=p_platform and d.invoice_id=p_invoice
   and d.status in('awaiting_verification','pending'))
   then raise exception 'A transfer proof for this invoice is already awaiting verification'; end if;

 select id into v_bank from public.ihlink_bank_accounts where is_active=true order by is_default desc,created_at asc limit 1;
 if v_bank is null then raise exception 'IHLink direct bank account has not been configured'; end if;

 insert into public.direct_transfer_submissions(
  user_id,platform_code,invoice_id,source_reference,bank_account_id,amount,sender_name,sender_bank,
  customer_reference,transferred_at,proof_storage_path,status
 ) values(
  auth.uid(),p_platform,p_invoice,p_source_reference,v_bank,v_balance,trim(p_sender_name),
  nullif(trim(p_sender_bank),''),trim(p_customer_reference),p_transferred_at,p_proof_storage_path,'awaiting_verification'
 ) returning id into v_id;
 return v_id;
end
$function$;

revoke all on function public.submit_direct_bank_transfer(text,uuid,text,numeric,text,text,text,timestamptz,text) from anon;
grant execute on function public.submit_direct_bank_transfer(text,uuid,text,numeric,text,text,text,timestamptz,text) to authenticated;

create or replace function public.review_direct_bank_transfer(p_submission uuid,p_decision text,p_note text default null)
returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare
 s public.direct_transfer_submissions%rowtype; new_status text;
 v_owner uuid; v_total numeric; v_paid numeric:=0; v_unit text; v_balance numeric; v_rows int;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if p_decision not in('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;

 select * into s from public.direct_transfer_submissions where id=p_submission for update;
 if s.id is null then raise exception 'Submission not found'; end if;
 if not (private.is_admin(array['super_admin'::public.user_role]) or private.business_staff_allowed(s.platform_code,'approve'))
   then raise exception 'Platform finance approval permission required'; end if;
 if s.status not in('awaiting_verification','pending') then raise exception 'Submission has already been reviewed'; end if;

 if p_decision='approved' then
   if s.platform_code='consult' then
     select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='engineering' then
     select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='print' then
     select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid
     from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=s.invoice_id for update of i;
   elsif s.platform_code='host' then
     select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid
     from public.host_invoices i where i.id=s.invoice_id for update;
   elsif s.platform_code in('fabrication','compute','academy','digital_business','business_centre') then
     select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit
     from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=s.invoice_id for update of i;
     if v_owner is not null and v_unit<>s.platform_code then raise exception 'Submission platform does not match invoice platform'; end if;
   else
     raise exception 'Unsupported direct-transfer platform';
   end if;

   if v_owner is null or v_owner<>s.user_id then raise exception 'Transfer submission does not match invoice owner'; end if;
   v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
   if v_balance<=0 then raise exception 'Invoice has already been settled'; end if;
   if s.amount<>v_balance then raise exception 'Transfer amount no longer matches the outstanding invoice balance'; end if;

   if s.platform_code='consult' then
     update public.consult_invoices set amount_paid=amount,status='paid',paid_at=now(),payment_reference=s.customer_reference,updated_at=now()
     where id=s.invoice_id;
   elsif s.platform_code='engineering' then
     update public.engineering_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   elsif s.platform_code='print' then
     update public.print_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   elsif s.platform_code='host' then
     update public.host_invoices set status='paid',paid_at=now(),payment_reference=s.customer_reference,updated_at=now() where id=s.invoice_id;
     update public.host_orders set payment_status='paid',paid_at=now(),status=case when status='awaiting_payment' then 'paid' else status end,updated_at=now()
     where id=(select order_id from public.host_invoices where id=s.invoice_id);
   else
     update public.business_invoices set amount_paid=amount,status='paid',updated_at=now() where id=s.invoice_id;
   end if;
   get diagnostics v_rows = row_count;
   if v_rows=0 then raise exception 'Invoice settlement failed'; end if;
   new_status='approved';
 else
   new_status='rejected';
 end if;

 update public.direct_transfer_submissions
 set status=new_status,admin_note=p_note,verified_by=auth.uid(),verified_at=now(),updated_at=now()
 where id=s.id and status in('awaiting_verification','pending');
 if not found then raise exception 'Submission has already been reviewed'; end if;

 return jsonb_build_object('id',s.id,'status',new_status,'platform',s.platform_code,'invoice_id',s.invoice_id);
end
$function$;

revoke all on function public.review_direct_bank_transfer(uuid,text,text) from anon;
grant execute on function public.review_direct_bank_transfer(uuid,text,text) to authenticated;

create or replace function public.finalize_schoolpro_billstack_transfer(
 p_intent uuid,p_transaction_ref text,p_verified_amount numeric,p_payload jsonb default '{}'::jsonb
) returns jsonb
language plpgsql security definer set search_path to ''
as $function$
declare
 i public.schoolpro_payment_intents%rowtype;
 inv public.schoolpro_invoices%rowtype;
 tx public.payment_transactions%rowtype;
 existing uuid; receipt uuid; new_paid numeric;
begin
 if p_verified_amount is null or p_verified_amount<=0 or p_verified_amount<>round(p_verified_amount,2)
    or nullif(btrim(p_transaction_ref),'') is null then
   raise exception 'Verified exact payment required';
 end if;

 select * into i from public.schoolpro_payment_intents where id=p_intent for update;
 if i.id is null then raise exception 'Payment intent not found'; end if;
 if i.gateway<>'billstack' then raise exception 'Payment intent provider mismatch'; end if;
 if i.status='successful' then
   if i.gateway_transaction_id=p_transaction_ref and i.amount=p_verified_amount then
     return jsonb_build_object('status','already_credited','reference',i.reference);
   end if;
   raise exception 'Payment intent already settled by another transaction';
 end if;
 if i.status<>'pending' then raise exception 'Payment intent is not payable'; end if;
 if p_verified_amount<>i.amount then raise exception 'Verified amount does not match invoice payment intent'; end if;

 select * into tx from public.payment_transactions
 where provider='billstack' and transaction_ref=p_transaction_ref for update;
 if tx.id is null
    or tx.status not in('verified','credited')
    or tx.credited_at is not null
    or tx.amount<>p_verified_amount
    or tx.currency<>'NGN'
    or tx.user_id is distinct from i.payer_user_id
    or tx.platform_code is distinct from 'schoolpro'
    or tx.virtual_account_id is distinct from i.virtual_account_id then
   raise exception 'Verified transaction ownership, platform or replay validation failed';
 end if;

 select id into existing from public.schoolpro_fee_payments where reference=p_transaction_ref limit 1;
 if existing is not null then raise exception 'Transaction already applied'; end if;

 select * into inv from public.schoolpro_invoices where id=i.invoice_id for update;
 if inv.id is null or inv.school_id<>i.school_id or inv.student_id<>i.student_id then
   raise exception 'Invoice mapping mismatch';
 end if;
 if inv.status in ('paid','waived') or inv.amount_paid+i.amount>inv.amount_due then
   raise exception 'Invoice is no longer payable';
 end if;

 insert into public.schoolpro_fee_payments(
   school_id,invoice_id,student_id,amount,method,reference,notes,recorded_by
 ) values(
   i.school_id,i.invoice_id,i.student_id,i.amount,'transfer',p_transaction_ref,
   'Verified BillStack bank transfer',i.payer_user_id
 ) returning id into receipt;

 new_paid:=inv.amount_paid+i.amount;
 update public.schoolpro_invoices
 set amount_paid=new_paid,
     status=case when new_paid>=amount_due then 'paid'::public.schoolpro_invoice_status
                 else 'part_paid'::public.schoolpro_invoice_status end,
     updated_at=now()
 where id=inv.id;

 update public.schoolpro_payment_intents
 set status='successful',gateway_transaction_id=p_transaction_ref,
     gateway_payload=coalesce(p_payload,'{}'::jsonb),credited_at=now(),updated_at=now()
 where id=i.id;

 update public.payment_transactions
 set status='credited',credited_at=now(),updated_at=now()
 where id=tx.id;

 return jsonb_build_object('status','credited','reference',i.reference,'receipt_id',receipt,'amount',i.amount);
end
$function$;

