create or replace function public.queue_failed_fulfilment_refund(
 p_product text,p_source_reference text,p_customer uuid,p_amount numeric,p_reason text
) returns uuid
language plpgsql security definer set search_path to ''
as $function$
declare
 v_id uuid; tx public.payment_transactions%rowtype; v_refund_amount numeric;
begin
 if nullif(btrim(p_product),'') is null or nullif(btrim(p_source_reference),'') is null then
   raise exception 'Product and payment reference are required';
 end if;
 select * into tx
 from public.payment_transactions
 where platform_code=p_product
   and (transaction_ref=p_source_reference or provider_reference=p_source_reference)
   and is_settled=true
   and status in ('verified','credited')
 order by credited_at desc nulls last, verified_at desc nulls last
 limit 1 for update;
 if tx.id is null then raise exception 'No verified settled payment matches this refund'; end if;
 if tx.user_id is distinct from p_customer then raise exception 'Refund customer does not match settled payment owner'; end if;

 v_refund_amount:=coalesce(tx.net_amount,tx.amount);
 if v_refund_amount is null or v_refund_amount<=0 then raise exception 'Settled payment has no refundable amount'; end if;
 if p_amount is null or p_amount<>v_refund_amount then raise exception 'Refund amount must equal the settled refundable amount'; end if;

 select id into v_id from public.finance_refund_requests
 where product=tx.platform_code
   and source_reference=coalesce(tx.transaction_ref,tx.provider_reference)
   and status in ('requested','approved','processing','processed')
 limit 1;
 if v_id is not null then return v_id; end if;

 begin
   insert into public.finance_refund_requests(
     refund_number,product,source_reference,customer_user_id,amount,currency,reason,status,requested_by
   ) values(
     'RFD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16)),
     tx.platform_code,coalesce(tx.transaction_ref,tx.provider_reference),tx.user_id,v_refund_amount,
     coalesce(tx.currency,'NGN'),coalesce(nullif(btrim(p_reason),''),'Paid fulfilment failed'),
     'requested',tx.user_id
   ) returning id into v_id;
 exception when unique_violation then
   select id into v_id from public.finance_refund_requests
   where product=tx.platform_code
     and source_reference=coalesce(tx.transaction_ref,tx.provider_reference)
     and status in ('requested','approved','processing','processed')
   limit 1;
 end;
 return v_id;
end
$function$;

