create or replace function public.review_finance_refund(p_refund uuid,p_decision text,p_note text default null)
returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare r public.finance_refund_requests%rowtype; tx public.payment_transactions%rowtype; ns text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not private.has_product_access('corporate','approve') then raise exception 'Finance approval permission required'; end if;
 if p_decision not in('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;
 select * into r from public.finance_refund_requests where id=p_refund for update;
 if r.id is null then raise exception 'Refund not found'; end if;
 if r.status<>'requested' then raise exception 'Refund has already been reviewed'; end if;
 select * into tx from public.payment_transactions
 where user_id=r.customer_user_id and platform_code=r.product
 and (transaction_ref=r.source_reference or provider_reference=r.source_reference)
 and is_settled=true and status in('verified','credited') order by created_at desc limit 1 for update;
 if tx.id is null then raise exception 'Original settled payment not found'; end if;
 if r.amount<>coalesce(tx.net_amount,tx.amount) or r.currency<>coalesce(tx.currency,'NGN') then
   raise exception 'Refund no longer matches original settlement';
 end if;
 ns:=case when p_decision='approved' then 'approved' else 'rejected' end;
 update public.finance_refund_requests set status=ns,reason=case when nullif(btrim(p_note),'') is null then reason else reason||' | Review: '||btrim(p_note) end,
 reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=r.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'finance_refund_'||ns,'corporate','finance_refund',r.id::text,
 jsonb_build_object('refund_number',r.refund_number,'source_reference',r.source_reference,'amount',r.amount,'currency',r.currency));
 return jsonb_build_object('id',r.id,'status',ns,'refund_number',r.refund_number);
end $function$;

create or replace function public.mark_finance_refund_processed(p_refund uuid,p_provider_reference text)
returns jsonb language plpgsql security definer set search_path to ''
as $function$
declare r public.finance_refund_requests%rowtype; tx public.payment_transactions%rowtype;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not private.has_product_access('corporate','approve') then raise exception 'Finance approval permission required'; end if;
 if nullif(btrim(p_provider_reference),'') is null then raise exception 'Refund provider reference is required'; end if;
 select * into r from public.finance_refund_requests where id=p_refund for update;
 if r.id is null then raise exception 'Refund not found'; end if;
 if r.status='processed' then return jsonb_build_object('id',r.id,'status','processed','refund_number',r.refund_number); end if;
 if r.status not in('approved','processing') then raise exception 'Refund must be approved before processing'; end if;
 select * into tx from public.payment_transactions
 where user_id=r.customer_user_id and platform_code=r.product
 and (transaction_ref=r.source_reference or provider_reference=r.source_reference)
 and is_settled=true and status in('verified','credited') order by created_at desc limit 1 for update;
 if tx.id is null or r.amount<>coalesce(tx.net_amount,tx.amount) or r.currency<>coalesce(tx.currency,'NGN') then
   raise exception 'Refund does not match original settlement';
 end if;
 update public.finance_refund_requests set status='processed',processed_at=now(),updated_at=now() where id=r.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'finance_refund_processed','corporate','finance_refund',r.id::text,
 jsonb_build_object('refund_number',r.refund_number,'source_reference',r.source_reference,'amount',r.amount,'currency',r.currency,'provider_reference',btrim(p_provider_reference)));
 return jsonb_build_object('id',r.id,'status','processed','refund_number',r.refund_number,'provider_reference',btrim(p_provider_reference));
end $function$;

