create or replace function public.submit_direct_bank_transfer(
 p_platform text,p_invoice uuid,p_source_reference text,p_amount numeric,p_sender_name text,p_sender_bank text,p_customer_reference text,p_transferred_at timestamptz default null,p_proof_storage_path text default null
) returns uuid language plpgsql security definer set search_path to ''
as $function$
declare v_bank uuid;v_id uuid;v_enabled boolean;v_owner uuid;v_total numeric;v_paid numeric:=0;v_unit text;v_balance numeric;
begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if p_platform='datasub' then raise exception 'DataSub requires immediate automated payment and fulfilment';end if;
 if p_platform='schoolpro' then raise exception 'SchoolPro bank transfers must use the dedicated school payment submission workflow';end if;
 if p_platform not in('host','consult','engineering','print','fabrication','compute','academy','digital_business','business_centre')
 then raise exception 'Direct transfer is not available for this platform';end if;
 if length(trim(coalesce(p_proof_storage_path,'')))=0 then raise exception 'Payment receipt/proof is required';end if;
 select direct_bank_transfer_enabled into v_enabled from public.payment_platform_settings where platform_code=p_platform;
 if not coalesce(v_enabled,false) then raise exception 'Direct bank transfer is not enabled for this platform';end if;
 if p_platform='consult' then
  select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.consult_invoices i join public.consult_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='engineering' then
  select pr.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.engineering_invoices i join public.engineering_projects pr on pr.id=i.project_id where i.id=p_invoice;
 elsif p_platform='print' then
  select o.user_id,i.amount,coalesce(i.amount_paid,0) into v_owner,v_total,v_paid from public.print_invoices i join public.print_orders o on o.id=i.order_id where i.id=p_invoice;
 elsif p_platform='host' then
  select i.user_id,i.amount,case when i.status='paid' then i.amount else 0 end into v_owner,v_total,v_paid from public.host_invoices i where i.id=p_invoice;
 elsif p_platform in('fabrication','compute','academy','digital_business','business_centre') then
  select o.user_id,i.amount,coalesce(i.amount_paid,0),o.unit_code into v_owner,v_total,v_paid,v_unit from public.business_invoices i join public.business_orders o on o.id=i.order_id where i.id=p_invoice;
  if v_owner is not null and v_unit<>p_platform then raise exception 'Invoice does not belong to the selected platform';end if;
 end if;
 if v_owner is null or v_owner<>auth.uid() then raise exception 'Invoice not found or does not belong to this account';end if;
 v_balance:=greatest(coalesce(v_total,0)-coalesce(v_paid,0),0);
 if v_balance<=0 then raise exception 'Invoice has no outstanding balance';end if;
 if p_amount<>v_balance then raise exception 'Transfer amount must equal the outstanding invoice balance';end if;
 if nullif(trim(coalesce(p_sender_name,'')),'') is null or nullif(trim(coalesce(p_customer_reference,'')),'') is null then raise exception 'Sender name and transfer reference are required';end if;
 if exists(select 1 from public.direct_transfer_submissions d where d.user_id=auth.uid() and d.platform_code=p_platform and d.invoice_id=p_invoice and d.status in('awaiting_verification','pending')) then raise exception 'A transfer proof for this invoice is already awaiting verification';end if;
 select id into v_bank from public.ihlink_bank_accounts where is_active=true order by is_default desc,created_at asc limit 1;
 if v_bank is null then raise exception 'IHLink direct bank account has not been configured';end if;
 insert into public.direct_transfer_submissions(user_id,platform_code,invoice_id,source_reference,bank_account_id,amount,sender_name,sender_bank,customer_reference,transferred_at,proof_storage_path,status)
 values(auth.uid(),p_platform,p_invoice,p_source_reference,v_bank,v_balance,trim(p_sender_name),nullif(trim(p_sender_bank),''),trim(p_customer_reference),p_transferred_at,p_proof_storage_path,'awaiting_verification') returning id into v_id;
 return v_id;
end $function$;
revoke all on function public.submit_direct_bank_transfer(text,uuid,text,numeric,text,text,text,timestamptz,text) from public,anon;
grant execute on function public.submit_direct_bank_transfer(text,uuid,text,numeric,text,text,text,timestamptz,text) to authenticated,service_role;

create or replace function private.enforce_super_admin_limit()
returns trigger
language plpgsql
security definer
set search_path to ''
as $function$
declare
 primary_email constant text := 'hassanisahassan12@gmail.com';
 current_super_admins integer;
begin
 if tg_op='UPDATE' and lower(old.email)=primary_email and
    (new.role<>'super_admin'::public.user_role or new.status<>'active') then
   raise exception 'The primary Super Administrator cannot be demoted or suspended.';
 end if;

 if new.role='super_admin'::public.user_role and
    (tg_op='INSERT' or old.role<>'super_admin'::public.user_role) then
   perform pg_advisory_xact_lock(hashtextextended('ihlink:super_admin_limit',0));
   select count(*) into current_super_admins
   from public.profiles
   where role='super_admin'::public.user_role and id<>new.id;
   if current_super_admins>=3 then
     raise exception 'IHLink allows the primary Super Administrator and up to two additional Super Administrators.';
   end if;
 end if;
 return new;
end
$function$;

revoke all on function private.enforce_super_admin_limit() from public,anon,authenticated;

create or replace function public.schoolpro_allocate_hostel(p_school uuid,p_student uuid,p_room uuid,p_session text)
returns uuid language plpgsql security definer set search_path to ''
as $function$
declare rm public.schoolpro_hostel_rooms;a uuid;
begin
 if not private.schoolpro_module_allowed(p_school,'hostel') then raise exception 'Module permission denied: hostel';end if;
 if not private.is_admin(array['super_admin']::public.user_role[]) and not public.schoolpro_member_can_manage(p_school) then raise exception 'Not authorized';end if;
 select * into rm from public.schoolpro_hostel_rooms where id=p_room and school_id=p_school for update;
 if rm.id is null then raise exception 'Room is unavailable';end if;
 if rm.occupied>=rm.capacity then raise exception 'Room is full';end if;
 if not exists(select 1 from public.schoolpro_students s where s.id=p_student and s.school_id=p_school and s.status='active') then
   raise exception 'Student does not belong to this school or is inactive';
 end if;
 update public.schoolpro_hostel_allocations set active=false
 where school_id=p_school and student_id=p_student and active=true;
 insert into public.schoolpro_hostel_allocations(school_id,student_id,room_id,session,active)
 values(p_school,p_student,p_room,p_session,true) returning id into a;
 update public.schoolpro_hostel_rooms
 set occupied=(select count(*) from public.schoolpro_hostel_allocations x where x.room_id=p_room and x.active=true)
 where id=p_room;
 return a;
end $function$;

create or replace function public.schoolpro_issue_library_loan(p_school uuid,p_book uuid,p_student uuid default null,p_member uuid default null,p_due timestamptz default null)
returns uuid language plpgsql security definer set search_path to ''
as $function$
declare b public.schoolpro_library_books;l uuid;
begin
 if not private.schoolpro_module_allowed(p_school,'library') then raise exception 'Module permission denied: library';end if;
 if not private.is_admin(array['super_admin']::public.user_role[]) and not public.schoolpro_member_can_manage(p_school) then raise exception 'Not authorized';end if;
 if (p_student is null)=(p_member is null) then raise exception 'Choose exactly one borrower';end if;
 select * into b from public.schoolpro_library_books where id=p_book and school_id=p_school for update;
 if b.id is null or b.available_copies<1 then raise exception 'Book unavailable';end if;
 if p_student is not null and not exists(
   select 1 from public.schoolpro_students s where s.id=p_student and s.school_id=p_school and s.status='active'
 ) then raise exception 'Student borrower does not belong to this school or is inactive';end if;
 if p_member is not null and not exists(
   select 1 from public.schoolpro_members m where m.id=p_member and m.school_id=p_school
 ) then raise exception 'Member borrower does not belong to this school';end if;
 insert into public.schoolpro_library_loans(school_id,book_id,student_id,member_id,due_at,fine,status)
 values(p_school,p_book,p_student,p_member,coalesce(p_due,now()+interval '14 days'),0,'borrowed') returning id into l;
 update public.schoolpro_library_books set available_copies=available_copies-1 where id=p_book;
 return l;
end $function$;

