create or replace function public.credit_verified_payment(p_user uuid,p_provider text,p_platform text,p_transaction_ref text,p_amount numeric,p_payload jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare tx public.payment_transactions%rowtype; fs public.payment_fee_settings%rowtype; before_balance numeric; after_balance numeric; ledger_id uuid; fee numeric:=0; net numeric; expected_platform text;
begin
 if p_user is null or p_amount is null or p_amount<=0 or p_amount<>round(p_amount,2)
    or nullif(btrim(p_provider),'') is null or nullif(btrim(p_transaction_ref),'') is null then raise exception 'Invalid verified credit'; end if;
 expected_platform:=lower(coalesce(nullif(btrim(p_platform),''),'corporate'));
 select * into tx from public.payment_transactions
 where lower(provider)=lower(btrim(p_provider)) and transaction_ref=btrim(p_transaction_ref) for update;
 if tx.id is null then raise exception 'Verified payment transaction not found'; end if;
 if tx.user_id is distinct from p_user then raise exception 'Payment owner mismatch'; end if;
 if tx.amount<>p_amount then raise exception 'Payment amount mismatch'; end if;
 if tx.currency is distinct from 'NGN' then raise exception 'Payment currency mismatch'; end if;
 if lower(coalesce(tx.platform_code,'')) is distinct from expected_platform then raise exception 'Payment platform mismatch'; end if;
 if tx.status not in ('verified','credited') or coalesce(tx.is_settled,false)<>true or tx.verified_at is null then
   raise exception 'Payment transaction is not verified and settled';
 end if;
 if tx.credited_at is not null then return jsonb_build_object('status','already_credited','transaction_ref',p_transaction_ref); end if;
 select * into fs from public.payment_fee_settings where provider=lower(p_provider) and platform_code=expected_platform and fee_code='wallet_funding' and enabled=true limit 1;
 if fs.id is not null and fs.customer_pays then
   if fs.fee_type='fixed' then fee:=fs.fee_value; else fee:=round((p_amount*fs.fee_value/100.0)::numeric,2); end if;
   if fs.minimum_fee is not null then fee:=greatest(fee,fs.minimum_fee); end if;
   if fs.maximum_fee is not null then fee:=least(fee,fs.maximum_fee); end if;
 end if;
 fee:=greatest(0,least(fee,p_amount)); net:=p_amount-fee;
 if net<=0 then raise exception 'Funding fee leaves no wallet credit'; end if;
 select id into ledger_id from public.wallet_ledger where reference='BILLSTACK:'||btrim(p_transaction_ref) for update;
 if ledger_id is not null then raise exception 'Funding ledger already exists without credited transaction marker'; end if;
 insert into public.datasub_wallets(user_id,balance,currency) values(p_user,0,'NGN') on conflict(user_id) do nothing;
 select balance into before_balance from public.datasub_wallets where user_id=p_user for update; after_balance:=before_balance+net;
 insert into public.wallet_ledger(user_id,entry_type,amount,reference,metadata,platform_code,provider,external_reference,internal_reference,direction,transaction_type,balance_before,balance_after,description)
 values(p_user,'credit',net,'BILLSTACK:'||btrim(p_transaction_ref),jsonb_build_object('gross_amount',p_amount,'customer_fee',fee,'fee_setting_id',fs.id)||coalesce(p_payload,'{}'::jsonb),expected_platform,tx.provider,tx.transaction_ref,tx.id::text,'CREDIT','wallet_funding',before_balance,after_balance,'Verified wallet funding');
 update public.datasub_wallets set balance=after_balance,updated_at=now() where user_id=p_user;
 update public.payment_transactions set status='credited',gross_amount=p_amount,customer_fee=fee,net_amount=net,fee_setting_id=fs.id,
 fee_snapshot=case when fs.id is null then '{}'::jsonb else jsonb_build_object('fee_type',fs.fee_type,'fee_value',fs.fee_value,'minimum_fee',fs.minimum_fee,'maximum_fee',fs.maximum_fee,'customer_pays',fs.customer_pays) end,
 credited_at=now(),updated_at=now() where id=tx.id and credited_at is null and is_settled=true and verified_at is not null;
 if not found then raise exception 'Payment transaction changed before credit'; end if;
 return jsonb_build_object('status','credited','transaction_ref',p_transaction_ref,'gross_amount',p_amount,'customer_fee',fee,'net_amount',net,'balance',after_balance);
end $$;
revoke all on function public.credit_verified_payment(uuid,text,text,text,numeric,jsonb) from public,anon,authenticated;
grant execute on function public.credit_verified_payment(uuid,text,text,text,numeric,jsonb) to service_role;

create or replace function public.finalize_schoolpro_payment(p_reference text,p_gateway_transaction_id text,p_verified_amount numeric,p_status text,p_payload jsonb default '{}'::jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare intent public.schoolpro_payment_intents%rowtype;
begin
 select * into intent from public.schoolpro_payment_intents where reference=btrim(p_reference) for update;
 if intent.id is null then raise exception 'Payment intent not found'; end if;
 if intent.status='successful' then return jsonb_build_object('status','already_credited','reference',intent.reference); end if;
 if intent.status<>'pending' then return jsonb_build_object('status','already_finalized','reference',intent.reference); end if;
 if lower(coalesce(p_status,''))='successful' then
   raise exception 'Legacy SchoolPro payment settlement is disabled; use the provider-bound BillStack finalizer';
 end if;
 update public.schoolpro_payment_intents set status='failed',gateway_transaction_id=nullif(btrim(p_gateway_transaction_id),''),
   gateway_payload=coalesce(p_payload,'{}'::jsonb),updated_at=now() where id=intent.id and status='pending';
 return jsonb_build_object('status','failed','reference',intent.reference,'amount',intent.amount);
end $$;
revoke all on function public.finalize_schoolpro_payment(text,text,numeric,text,jsonb) from public,anon,authenticated;
grant execute on function public.finalize_schoolpro_payment(text,text,numeric,text,jsonb) to service_role;

