create or replace function public.queue_failed_fulfilment_refund(p_product text,p_source_reference text,p_customer uuid,p_amount numeric,p_reason text)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_id uuid; tx public.payment_transactions%rowtype; v_refund_amount numeric;
begin
 if nullif(btrim(p_product),'') is null or nullif(btrim(p_source_reference),'') is null then raise exception 'Product and payment reference are required'; end if;
 select * into tx from public.payment_transactions
 where platform_code=btrim(p_product)
 and (transaction_ref=btrim(p_source_reference) or provider_reference=btrim(p_source_reference))
 and is_settled=true and status in('verified','credited')
 order by credited_at desc nulls last,verified_at desc nulls last limit 1 for update;
 if tx.id is null then raise exception 'No verified settled payment matches this refund'; end if;
 if tx.user_id is distinct from p_customer then raise exception 'Refund customer does not match settled payment owner'; end if;
 v_refund_amount:=coalesce(tx.net_amount,tx.amount);
 if v_refund_amount is null or v_refund_amount<=0 then raise exception 'Settled payment has no refundable amount'; end if;
 if p_amount is null or p_amount<>v_refund_amount then raise exception 'Refund amount must equal the settled refundable amount'; end if;
 select id into v_id from public.finance_refund_requests where payment_transaction_id=tx.id and status in('requested','approved','processing','processed') limit 1;
 if v_id is not null then return v_id; end if;
 begin
  insert into public.finance_refund_requests(refund_number,product,source_reference,payment_transaction_id,customer_user_id,amount,currency,reason,status,requested_by)
  values('RFD-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,16)),tx.platform_code,tx.transaction_ref,tx.id,tx.user_id,v_refund_amount,coalesce(tx.currency,'NGN'),coalesce(nullif(btrim(p_reason),''),'Paid fulfilment failed'),'requested',tx.user_id)
  returning id into v_id;
 exception when unique_violation then
  select id into v_id from public.finance_refund_requests where payment_transaction_id=tx.id and status in('requested','approved','processing','processed') limit 1;
 end;
 return v_id;
end $$;
revoke all on function public.queue_failed_fulfilment_refund(text,text,uuid,numeric,text) from public,anon,authenticated;
grant execute on function public.queue_failed_fulfilment_refund(text,text,uuid,numeric,text) to service_role;

create or replace function public.review_finance_refund(p_refund uuid,p_decision text,p_note text default null)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.finance_refund_requests%rowtype; tx public.payment_transactions%rowtype; ns text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not private.has_product_access('corporate','approve') then raise exception 'Finance approval permission required'; end if;
 if p_decision not in('approved','rejected') then raise exception 'Decision must be approved or rejected'; end if;
 select * into r from public.finance_refund_requests where id=p_refund for update;
 if r.id is null then raise exception 'Refund not found'; end if;
 if r.status<>'requested' then raise exception 'Refund has already been reviewed'; end if;
 if r.payment_transaction_id is null then raise exception 'Refund is not bound to a canonical payment transaction'; end if;
 select * into tx from public.payment_transactions where id=r.payment_transaction_id for update;
 if tx.id is null or tx.user_id is distinct from r.customer_user_id or tx.platform_code is distinct from r.product
 or tx.transaction_ref is distinct from r.source_reference or tx.is_settled<>true or tx.status not in('verified','credited')
 or r.amount<>coalesce(tx.net_amount,tx.amount) or r.currency<>coalesce(tx.currency,'NGN') then raise exception 'Refund no longer matches original settlement'; end if;
 ns:=p_decision;
 update public.finance_refund_requests set status=ns,reason=case when nullif(btrim(p_note),'') is null then reason else reason||' | Review: '||btrim(p_note) end,reviewed_by=auth.uid(),reviewed_at=now(),updated_at=now() where id=r.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'finance_refund_'||ns,'corporate','finance_refund',r.id::text,jsonb_build_object('refund_number',r.refund_number,'payment_transaction_id',r.payment_transaction_id,'source_reference',r.source_reference,'amount',r.amount,'currency',r.currency));
 return jsonb_build_object('id',r.id,'status',ns,'refund_number',r.refund_number);
end $$;
revoke all on function public.review_finance_refund(uuid,text,text) from public,anon;
grant execute on function public.review_finance_refund(uuid,text,text) to authenticated,service_role;

create or replace function public.mark_finance_refund_processed(p_refund uuid,p_provider_reference text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare r public.finance_refund_requests%rowtype; tx public.payment_transactions%rowtype; v_ref text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if not private.has_product_access('corporate','approve') then raise exception 'Finance approval permission required'; end if;
 v_ref:=nullif(btrim(p_provider_reference),''); if v_ref is null then raise exception 'Refund provider reference is required'; end if;
 select * into r from public.finance_refund_requests where id=p_refund for update;
 if r.id is null then raise exception 'Refund not found'; end if;
 if r.status='processed' then
   if r.provider_refund_reference is distinct from v_ref then raise exception 'Refund was already processed with a different provider reference'; end if;
   return jsonb_build_object('id',r.id,'status','processed','refund_number',r.refund_number,'provider_reference',r.provider_refund_reference);
 end if;
 if r.status not in('approved','processing') then raise exception 'Refund must be approved before processing'; end if;
 if r.payment_transaction_id is null then raise exception 'Refund is not bound to a canonical payment transaction'; end if;
 select * into tx from public.payment_transactions where id=r.payment_transaction_id for update;
 if tx.id is null or tx.user_id is distinct from r.customer_user_id or tx.platform_code is distinct from r.product
 or tx.transaction_ref is distinct from r.source_reference or tx.is_settled<>true or tx.status not in('verified','credited')
 or r.amount<>coalesce(tx.net_amount,tx.amount) or r.currency<>coalesce(tx.currency,'NGN') then raise exception 'Refund does not match original settlement'; end if;
 if exists(select 1 from public.finance_refund_requests x where x.id<>r.id and x.provider_refund_reference=v_ref and x.status='processed') then raise exception 'Refund provider reference has already been used'; end if;
 update public.finance_refund_requests set status='processed',provider_refund_reference=v_ref,processed_at=now(),updated_at=now() where id=r.id;
 insert into public.audit_logs(actor_id,action,product,target_type,target_id,metadata)
 values(auth.uid(),'finance_refund_processed','corporate','finance_refund',r.id::text,jsonb_build_object('refund_number',r.refund_number,'payment_transaction_id',r.payment_transaction_id,'source_reference',r.source_reference,'amount',r.amount,'currency',r.currency,'provider_reference',v_ref));
 return jsonb_build_object('id',r.id,'status','processed','refund_number',r.refund_number,'provider_reference',v_ref);
end $$;
revoke all on function public.mark_finance_refund_processed(uuid,text) from public,anon;
grant execute on function public.mark_finance_refund_processed(uuid,text) to authenticated,service_role;
create unique index if not exists finance_refunds_processed_provider_ref_unique on public.finance_refund_requests(provider_refund_reference) where provider_refund_reference is not null and status='processed';

