create policy "academic_documents_staff" on public.schoolpro_academic_documents
for all to authenticated
using (
 public.schoolpro_member_can_manage(school_id)
 or exists (
   select 1 from public.schoolpro_members m
   where m.school_id = schoolpro_academic_documents.school_id
     and m.user_id = auth.uid()
     and m.role::text = any(array['registrar','exam_officer','head_teacher','administrator','proprietor'])
 )
)
with check (
 public.schoolpro_member_can_manage(school_id)
 or exists (
   select 1 from public.schoolpro_members m
   where m.school_id = schoolpro_academic_documents.school_id
     and m.user_id = auth.uid()
     and m.role::text = any(array['registrar','exam_officer','head_teacher','administrator','proprietor'])
 )
);

